62	/**
63	 * カードタッチで勤怠を記録
64	 * キオスク端末から呼び出される主要な関数
65	 */
66	export async function recordAttendance(cardId: string): Promise<{ 
67	  success: boolean; 
68	  message: string; 
69	  user: { display_name: string | null } | null; 
70	  type: 'in' | 'out' | null 
71	}> {
72	  const supabase = await createSupabaseAdminClient();
73	  
74	  const normalizedCardId = cardId.replace(/:/g, '').toLowerCase();
75	
76	  const { data: attendanceUser, error: attendanceUserError } = await supabase
77	    .schema('attendance')
78	    .from('users')
79	    .select('supabase_auth_user_id, card_id')
80	    .eq('card_id', normalizedCardId)
81	    .single();
82	
83	  if (attendanceUserError || !attendanceUser) {
84	    return { success: false, message: '未登録のカードです。', user: null, type: null };
85	  }
86	
87	  const userId = attendanceUser.supabase_auth_user_id;
88	  
89	  // member.members テーブルから Discord UID を取得
90	  const { data: memberData } = await supabase
91	    .schema('member')
92	    .from('members')
93	    .select('discord_uid')
94	    .eq('supabase_auth_user_id', userId)
95	    .single();
96	  
97	  let userDisplayName = '名無しさん';
98	  
99	  // Discord UIDがある場合、APIから本名を取得
100	  if (memberData?.discord_uid) {
101	    const { data: nickname } = await fetchMemberNickname(memberData.discord_uid);
102	    if (nickname) {
103	      userDisplayName = nickname;
104	    }
105	  }
106	
107	  const today = format(new Date(), 'yyyy-MM-dd');
108	  const now = new Date();
109	
110	  const { data: recentAttendances } = await supabase
111	    .schema('attendance')
112	    .from('attendances')
113	    .select('*')
114	    .eq('user_id', userId)
115	    .eq('date', today)
116	    .order('timestamp', { ascending: false })
117	    .limit(1);
118	
119	  let attendanceType: 'in' | 'out' = 'in';
120	  if (recentAttendances && recentAttendances.length > 0) {
121	    const lastType = recentAttendances[0].type;
122	    attendanceType = lastType === 'in' ? 'out' : 'in';
123	  }
124	
125	  const { error: insertError } = await supabase
126	    .schema('attendance')
127	    .from('attendances')
128	    .insert({
129	      user_id: userId,
130	      type: attendanceType,
131	      timestamp: now.toISOString(),
132	      date: today,
133	    });
134	
135	  if (insertError) {
136	    console.error('Error inserting attendance:', insertError);
137	    return { 
138	      success: false, 
139	      message: '勤怠記録に失敗しました。', 
140	      user: { display_name: userDisplayName }, 
141	      type: null 
142	    };
143	  }
144	
145	  const message = attendanceType === 'in' ? `${userDisplayName}さん、おはようございます!` : `${userDisplayName}さん、お疲れ様でした!`;
146	  
147	  revalidatePath('/dashboard');
148	  revalidatePath('/admin');
149	  
150	  return { 
151	    success: true, 
152	    message, 
153	    user: { display_name: userDisplayName }, 
154	    type: attendanceType 
155	  };
156	}
157	
158	/**
159	 * 仮登録トークンを作成
160	 */
161	export async function createTempRegistration(cardId: string): Promise<{ 
162	  success: boolean; 
163	  token?: string; 
164	  message: string 
165	}> {
166	  const supabase = await createSupabaseAdminClient();
167	  const normalizedCardId = cardId.replace(/:/g, '').toLowerCase();
168	
169	  const { data: existingCard } = await supabase
170	    .schema('attendance')
171	    .from('users')
172	    .select('card_id')
173	    .eq('card_id', normalizedCardId)
174	    .single();
175	
176	  if (existingCard) {
177	    return { success: false, message: 'このカードは既に登録されています。' };
178	  }
179	
180	  const token = randomUUID();
181	  const expiresAt = new Date();
182	  expiresAt.setHours(expiresAt.getHours() + 24);
183	
184	  const { error } = await supabase
185	    .schema('member')
186	    .from('temp_registrations')
187	    .insert({
188	      token,
189	      card_id: normalizedCardId,
190	      expires_at: expiresAt.toISOString(),
191	    });
192	
193	  if (error) {
194	    console.error('Error creating temp registration:', error);
195	    return { success: false, message: '仮登録の作成に失敗しました。' };
196	  }
197	
198	  return { 
199	    success: true, 
200	    token, 
201	    message: `登録URL: ${process.env.NEXT_PUBLIC_APP_URL}/register/${token}` 
202	  };
203	}
204	
205	/**
206	 * ユーザーの勤怠統計を取得
207	 */
208	export async function getUserAttendanceStats(userId: string, days: number = 30) {
209	  const supabase = await createSupabaseServerClient();
210	  const startDate = format(subDays(new Date(), days), 'yyyy-MM-dd');
211	
212	  const { data: attendances } = await supabase
213	    .schema('attendance')
214	    .from('attendances')
215	    .select('*')
216	    .eq('user_id', userId)
217	    .gte('date', startDate)
218	    .order('timestamp', { ascending: true });
219	
220	  if (!attendances || attendances.length === 0) {
221	    return {
222	      totalDays: 0,
223	      totalTime: 0,
224	      averageTime: 0,
225	    };
226	  }
227	
228	  const dailySessions = new Map<string, { in: Date | null; totalSeconds: number }>();
229	
230	  for (const att of attendances) {
231	    const date = att.date;
232	    if (!date) continue;
233	
234	    if (!dailySessions.has(date)) {
235	      dailySessions.set(date, { in: null, totalSeconds: 0 });
236	    }
237	
238	    const session = dailySessions.get(date)!;
239	    
240	    if (att.type === 'in') {
241	      session.in = new Date(att.timestamp);
242	    } else if (att.type === 'out' && session.in) {
243	      const outTime = new Date(att.timestamp);
244	      const seconds = differenceInSeconds(outTime, session.in);
245	      session.totalSeconds += seconds;
246	      session.in = null;
247	    }
248	  }
249	
250	  let totalSeconds = 0;
251	  let daysWithActivity = 0;
252	
253	  for (const session of dailySessions.values()) {
254	    if (session.totalSeconds > 0) {
255	      totalSeconds += session.totalSeconds;
256	      daysWithActivity++;
257	    }
258	  }
259	
260	  return {
261	    totalDays: daysWithActivity,
262	    totalTime: totalSeconds,
263	    averageTime: daysWithActivity > 0 ? totalSeconds / daysWithActivity : 0,
264	  };
265	}
266	
267	/**
268	 * ユーザーの最近の勤怠記録を取得
269	 */
270	export async function getUserRecentAttendance(userId: string, limit: number = 10) {
271	  const supabase = await createSupabaseServerClient();
272	
273	  const { data: attendances, error } = await supabase
274	    .schema('attendance')
275	    .from('attendances')
276	    .select('*')
277	    .eq('user_id', userId)
278	    .order('timestamp', { ascending: false })
279	    .limit(limit);
280	
281	  if (error) {
282	    console.error('Error fetching recent attendance:', error);
283	    return [];
284	  }
285	
286	  return attendances || [];
287	}
